"""Registry of visits by page."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered visit."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(visit):
    """Add one visit to the registry."""
    _ALL.append(visit)


def find(page):
    """Return the visits registered under this page."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.page, []).append(x)
    return _BY_KEY.get(page, [])

